class AuditLogger:
    def record(self, message):
        print(f"[AUDIT] {message}")


class Order:
    def __init__(self):
        self.price = 250.0
        self.last_accessed_at = None
        self.audit_logger = AuditLogger()

    def get_total(self):
        self.last_accessed_at = datetime.now()      # changes state

        self.audit_logger.record("Total viewed")    # performs I/O

        return self._calculate_total()

    def _calculate_total(self):
        return self.price


if __name__ == "__main__":
    order = Order()
    # Calling a plain-looking getter secretly mutates state and performs I/O
    print(f"Total: {order.get_total()}")

