import java.time.Instant;

class AuditLogger {
    void record(String message) {
        System.out.println("[AUDIT] " + message);
    }
}

class Order {

    private double price = 250.0;
    private Instant lastAccessedAt;
    private AuditLogger auditLogger = new AuditLogger();

    double getTotal() {

        lastAccessedAt = Instant.now();      // changes state

        auditLogger.record("Total viewed");  // performs I/O

        return calculateTotal();
    }

    private double calculateTotal() {
        return price;
    }
}

public class Main {
    public static void main(String[] args) {
        Order order = new Order();
        // Calling a plain-looking getter secretly mutates state and performs I/O
        System.out.println("Total: " + order.getTotal());
    }
}

