#include <iostream>
#include <chrono>
#include <string>

class AuditLogger {
public:
    void record(const std::string& message) {
        std::cout << "[AUDIT] " << message << std::endl;
    }
};

class Order {
public:
    Order() : price_(250.0) {}

    double getTotal() {
        lastAccessedAt_ = std::chrono::system_clock::now(); // changes state

        auditLogger_.record("Total viewed"); // performs I/O

        return calculateTotal();
    }

private:
    double calculateTotal() const { return price_; }

    double price_;
    std::chrono::system_clock::time_point lastAccessedAt_;
    AuditLogger auditLogger_;
};

int main() {
    Order order;
    // Calling a plain-looking getter secretly mutates state and performs I/O
    std::cout << "Total: " << order.getTotal() << std::endl;
    return 0;
}

