class Person:
    def __init__(self):
        self.age = 0

    def set_age(self, age):
        # Astonishing behavior: silently clamps instead of rejecting or accepting as-is
        self.age = max(age, 0)

    def get_age(self):
        return self.age


if __name__ == "__main__":
    person = Person()
    person.set_age(-5)
    # Caller believes age is -5, but it was silently changed to 0
    print(f"Stored age: {person.get_age()}")

